  function table(headings,rows,empty='No records to show yet.') {return rows.length?'<div class="owner-table-wrap"><table class="owner-table"><thead><tr>'+headings.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>':'<div class="owner-empty">'+esc(empty)+'</div>';}
