    $('owner-tabs').hidden=s.tabs.length<2;$('owner-tabs').innerHTML=s.tabs.map(([id,label])=>'<button type="button" data-tab="'+id+'"'+(tab===id?' aria-current="page"':'')+'>'+label+'</button>').join('');loadView();if(fromMobileMenu)$('owner-main').focus({preventScroll:true});
