    const iframe=$('owner-embedded-workspace');iframe.addEventListener('load',()=>{try{const doc=iframe.contentDocument;doc.body.classList.add('owner-console-embedded');doc.body.dataset.ownerPane=pane;const css=doc.createElement('link');css.rel='stylesheet';css.href='/owner-console-embed.css';doc.head.append(css);doc.addEventListener('click',event=>{const link=event.target.closest('a');if(!link)return;const href=link.getAttribute('href')||'';if(/^(?:\/)?(?:admin|coverage|growth)\.html(?:[?#]|$)/.test(href)){event.preventDefault();selectRoute(href.includes('growth')?'marketing':'degrees',href.includes('growth')?'activity':href.includes('coverage')?'coverage':'research');}});}catch{notice('This workspace could not be embedded. Refresh your owner session and try again.',true);}});
