    $('owner-view').innerHTML=financeTotals+'<section class="owner-panel"><div class="owner-panel-head"><div><h2>'+esc(config.title)+'</h2><p>'+esc(config.description)+'</p></div>'+button('new-record','Add '+config.singular,false)+'</div><form id="owner-filter-form" class="owner-filterbar"><label class="owner-field"><span>Find a '+esc(config.singular)+'</span><input type="search" name="q" value="'+esc(query.q||'')+'" maxlength="100" placeholder="Search records"></label>'+field('status','Status',query.status||'',[['','All statuses'],...config.statuses])+'<button type="submit" class="owner-button owner-secondary">Apply</button></form>'+table([name==='finance'?'Financial entry':human(config.singular),'Status',name==='tasks'?'Due':name==='support'?'Priority':'Updated','Action'],rows,'No '+config.title.toLowerCase()+' match this view.')+(resourceCursor?'<div class="owner-actions">'+button('resource-more','Next page',true)+'</div>':'')+'</section>';
