  function parseBlocks(value) {return String(value||'').split(/\n\s*\n/).map(s=>s.trim()).filter(Boolean).map(text=>/^##\s/.test(text)?{type:'heading',level:2,text:text.replace(/^##\s+/,'')}:text.split('\n').every(line=>/^-\s/.test(line))?{type:'list',items:text.split('\n').map(line=>line.replace(/^-\s+/,''))}:{type:'paragraph',text});}
