    const lifecycle=item&&contentType!=='starters'?'<hr class="owner-divider"><div class="owner-actions">'+button('preview-content','Preview this saved version',true)+button('review-content','Mark saved version reviewed',true)+(contentType!=='campaigns'?button('publish-content','Publish reviewed version'):'')+button('archive-content','Archive',true)+'</div><p class="owner-subtle">Save edits first. Publishing requires review of that exact saved version. '+(item.status==='published'?'The last published version stays live while you edit.':'')+'</p>'+(contentVersions.length?'<details><summary>Saved version history</summary><ul>'+contentVersions.map(version=>'<li>Revision '+esc(version.revision)+' · '+esc(human(version.action))+' · '+esc(date(version.createdAt))+'</li>').join('')+'</ul></details>':''):contentType==='starters'&&item?'<hr class="owner-divider"><div class="owner-actions">'+button('archive-content','Archive guide',true)+'</div>':'';
