    if(b.id==='owner-mobile-backdrop')return menu(false);
    if(b.id==='owner-discard-stay'){$('owner-discard').close();pendingLeave=null;return;}
    if(b.id==='owner-discard-leave'){$('owner-discard').close();dirty=false;const action=pendingLeave;pendingLeave=null;action?.();return;}
    if(b.id==='owner-dialog-close'){event.preventDefault();return guard(closeDialog);}
    if(b.dataset.section)return guard(()=>{if($('owner-dialog').open)closeDialog();selectRoute(b.dataset.section);});
