    if(b.dataset.studentPage)return perform(()=>students(generation,{page:b.dataset.studentPage,query:$('owner-student-search')?.elements.query.value||''}));
    if(b.dataset.searchReport)return perform(async()=>{const data=await api('/api/owner/search-console/imports/'+encodeURIComponent(b.dataset.searchReport));dialog('<p class="owner-subtle">'+esc(human(data.import?.dimension))+' report · '+esc(data.import?.period?.startDate)+' to '+esc(data.import?.period?.endDate)+'. Rows are kept in their original report dimension.</p>'+table(['Row','Clicks','Impressions','Reported CTR','Position'],list(data.rows).slice(0,200).map(row=>'<tr><td>'+esc(row.value)+'</td><td>'+esc(row.clicks??'Unknown')+'</td><td>'+esc(row.impressions??'Unknown')+'</td><td>'+esc(typeof row.reportedCtr==='number'?(row.reportedCtr*100).toFixed(2)+'%':'Unknown')+'</td><td>'+esc(row.position??'Unknown')+'</td></tr>'),'No rows were returned.')+(list(data.rows).length>200?'<p class="owner-subtle">Showing the first 200 rows of this imported report.</p>':''),'Imported search report');});
    if(b.dataset.connectionId)return connectionDialog();
    const action=b.dataset.action|| (b.id==='owner-refresh'?'refresh':'');if(!action)return;
    if(action==='close-dialog')return guard(closeDialog);
    if(action==='new-task'){activeResource='tasks';return editResource();}
    if(action==='new-record')return editResource();
    if(action==='new-content')return contentDialog();
    if(action==='back-content-editor')return perform(()=>contentDialog(selectedItem?.id));
    if(action==='moderate-reports')return window.DegreeCommunity.openModeration();
    if(action==='moderate-outcomes')return window.DegreeEvidence.moderate();
