      if(action==='refresh')return guard(loadView);
      if(action==='resource-more')return resource(activeResource,generation,{cursor:resourceCursor});
      if(action==='sync-students'){const data=await api('/api/owner/students/sync',{method:'POST',body:{}});await students(generation);notice(data.complete?'Account directory synced.':'The next page of accounts is ready to sync. Choose Sync again to continue.');}
      if(action==='check-dns'){await api('/api/owner/search-console/check-dns',{method:'POST',body:{}});await searchConsole(generation);notice('DNS check completed. Google ownership still needs to be verified in Search Console.');}
