      if(['test-directory-key','confirm-disconnect-directory-key'].includes(action)){await api('/api/owner/connections/supabase-admin'+(action==='test-directory-key'?'/test':''),{method:action==='test-directory-key'?'POST':'DELETE',body:{revision:selectedItem.revision}});closeDialog();await connectionView(generation);notice('Account directory connection updated.');}
